<script>
(function(){var root=document.getElementById('dau-tu-can-ban');if(!root)return;var tabs=Array.prototype.slice.call(root.querySelectorAll('[role="tab"]'));var panels=Array.prototype.slice.call(root.querySelectorAll('[role="tabpanel"]'));function activate(index,focus){tabs.forEach(function(tab,i){tab.setAttribute('aria-selected',i===index?'true':'false');tab.tabIndex=i===index?0:-1;panels[i].hidden=i!==index;});if(focus)tabs[index].focus();}tabs.forEach(function(tab,index){tab.addEventListener('click',function(){activate(index,false);});tab.addEventListener('keydown',function(event){var next=index;if(event.key==='ArrowRight')next=(index+1)%tabs.length;else if(event.key==='ArrowLeft')next=(index+tabs.length-1)%tabs.length;else if(event.key==='Home')next=0;else if(event.key==='End')next=tabs.length-1;else return;event.preventDefault();activate(next,true);});});activate(0,false);})();
